const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const ts = require('typescript');

// Generated by build_library_sorting_json from the v1.5.1 player tag.
const reversedV151 = require('./fixtures/library-sorting-v1.5.1.json');

function load(file, imports = {}) {
  const source = fs.readFileSync(`${__dirname}/../${file}`, 'utf8');
  const javascript = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 },
  }).outputText;
  const module = { exports: {} };
  vm.runInNewContext(javascript, {
    module,
    exports: module.exports,
    require: (name) => {
      assert.ok(name in imports, `Unexpected import: ${name}`);
      return imports[name];
    },
    setTimeout: (resolve) => resolve(),
  });
  return module.exports;
}

const sortModes = load('src/data/librarySortModes.ts');
const { librarySortOptions } = sortModes;
const { RemoteApi } = load('src/data/RemoteApi.ts', {
  './redirectGuard': {},
  './cryptoUtils': {},
  './dacMode': {},
  './SettingsApi': {},
  './PluginsApi': {},
  './HttpTransport': {},
  './librarySortModes': sortModes,
});
const { isServerOrderedAlbumSort, requestLibrarySortChange } = load('src/session/librarySorting.ts', {
  '../data/librarySortModes': sortModes,
});
const plain = (value) => JSON.parse(JSON.stringify(value));
const availabilityV160 = [true, true, true, true, false, false, false, false, true];

async function checkSnapshots(api) {
  api.jsonGet = async () => reversedV151;
  const reversed = plain(await api.librarySorting());
  assert.deepEqual(reversed.albums, reversedV151.albums);
  assert.deepEqual(reversed.albumArtists, reversedV151.album_artists);
  assert.equal(isServerOrderedAlbumSort(reversed.albums), true);
  assert.deepEqual(plain(librarySortOptions('albums', reversed.albums.available)
    .map(({ mode, available }) => [mode, available])), [[0, true], [1, true], [2, false]]);
  assert.deepEqual(plain(librarySortOptions('albums', availabilityV160).map(({ mode }) => mode)), [0, 1, 2, 3, 8]);

  api.jsonGet = async () => Object.fromEntries(Object.entries(reversedV151).map(([scope, value]) => [
    scope, { configured: value.configured, effective: value.effective, available: value.available },
  ]));
  const legacy = await api.librarySorting();
  assert.equal(legacy.albums.reverse, false, 'v1.5.0 replies omit reverse');
  assert.equal(isServerOrderedAlbumSort(legacy.albums), false);
  assert.equal(isServerOrderedAlbumSort(null), false);

  for (const mode of [3, 8]) {
    api.jsonGet = async () => ({
      ...reversedV151,
      albums: { configured: mode, effective: mode, reverse: false, available: availabilityV160 },
    });
    const current = await api.librarySorting();
    assert.equal(current.albums.configured, mode);
    assert.equal(current.albums.available.length, 9);
    assert.equal(isServerOrderedAlbumSort(current.albums), true);
  }

  api.jsonGet = async () => ({
    ...reversedV151,
    albums: { ...reversedV151.albums, configured: 3, effective: 3 },
  });
  assert.equal((await api.librarySorting()).albums.effective, 3, 'v1.5.1 can report a device-only album mode');
}

async function checkInvalidSnapshots(api) {
  for (const [scope, patch] of [
    ['albums', { configured: 4 }],
    ['albums', { configured: 8 }],
    ['albums', { effective: 8 }],
    ['albums', { available: [true, true, true, true] }],
    ['albums', { available: [true, true, 0] }],
    ['albums', { reverse: 'true' }],
    ['artists', { available: availabilityV160 }],
    ['album_artists', { available: availabilityV160 }],
    ['artists', { configured: 3 }],
  ]) {
    api.jsonGet = async () => ({ ...reversedV151, [scope]: { ...reversedV151[scope], ...patch } });
    await assert.rejects(api.librarySorting(), /Invalid library sorting response/);
  }
}

async function checkModeChanges(api) {
  const commands = [];
  const isCurrent = () => true;
  api.command = async (...args) => commands.push(plain(args));
  api.jsonGet = async () => reversedV151;
  const reversed = await api.librarySorting();

  api.jsonGet = async () => assert.fail('Rows that cannot change must issue no reads');
  for (const mode of [0, 2, 3, 8]) {
    assert.equal(await requestLibrarySortChange(api, reversed, 'albums', mode, isCurrent), undefined);
  }
  assert.deepEqual(commands, [], 'Checked, unavailable, and absent rows must issue no writes');

  for (const cachedReverse of [true, false]) {
    commands.length = 0;
    let reads = 0;
    api.jsonGet = async () => {
      reads++;
      if (!commands.length) return reversedV151;
      return {
        ...reversedV151,
        albums: { ...reversedV151.albums, configured: 1, effective: 1, reverse: reads === 3 },
      };
    };
    const cached = { ...reversed, albums: { ...reversed.albums, reverse: cachedReverse } };
    const updated = await requestLibrarySortChange(api, cached, 'albums', 1, isCurrent);
    assert.equal(reads, 3, 'Read the player before writing and wait for its original direction');
    assert.equal(updated.albums.reverse, true);
    assert.deepEqual(commands, [['/library/sorting', [['scope', 'albums'], ['mode', '1']]]]);
  }

  commands.length = 0;
  const reversedV160 = { ...reversedV151, albums: { ...reversedV151.albums, available: availabilityV160 } };
  api.jsonGet = async () => reversedV160;
  const current = await api.librarySorting();
  let reads = 0;
  api.jsonGet = async () => {
    reads++;
    if (!commands.length) return reversedV160;
    return {
      ...reversedV160,
      albums: { ...reversedV160.albums, configured: 8, effective: 8, reverse: reads === 2 },
    };
  };
  const rating = await requestLibrarySortChange(api, current, 'albums', 8, isCurrent);
  assert.equal(reads, 3, 'Rating must confirm forward even when the previous mode was reversed');
  assert.equal(rating.albums.reverse, false);
  assert.deepEqual(commands, [['/library/sorting', [['scope', 'albums'], ['mode', '8']]]]);
  await api.setLibrarySorting('albums', 3);
  assert.deepEqual(commands[1], ['/library/sorting', [['scope', 'albums'], ['mode', '3']]]);
  await assert.rejects(api.setLibrarySorting('genres', 0), /Invalid sorting scope/);
  await assert.rejects(api.setLibrarySorting('artists', 8), /Invalid sort mode for scope/);
  await assert.rejects(api.setLibrarySorting('album_artists', 3), /Invalid sort mode for scope/);
  await assert.rejects(api.setLibrarySorting('albums', 4), /Invalid sort mode for scope/);
}

async function checkPreflightGuards(api) {
  api.jsonGet = async () => reversedV151;
  const cached = await api.librarySorting();
  api.command = async () => assert.fail('A superseded or unavailable change must issue no writes');

  for (const patch of [{ configured: 1, effective: 1 }, { available: [true, false, false] }]) {
    const reply = { ...reversedV151, albums: { ...reversedV151.albums, ...patch } };
    api.jsonGet = async () => reply;
    const updated = await requestLibrarySortChange(api, cached, 'albums', 1, () => true);
    assert.deepEqual(plain(updated.albums), reply.albums);
  }

  let owned = true;
  api.jsonGet = async () => {
    owned = false;
    return reversedV151;
  };
  assert.equal(await requestLibrarySortChange(api, cached, 'albums', 1, () => owned), undefined);
}

async function main() {
  const api = new RemoteApi({});
  await checkSnapshots(api);
  await checkInvalidSnapshots(api);
  await checkModeChanges(api);
  await checkPreflightGuards(api);
  console.log('Library sorting compatibility, capability rows, and direction confirmation passed');
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
